/**
 * Jinx Engineer + Legion: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Engineer
 * Wiki: https://wiki.bloodontheclocktower.com/Legion
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L117). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData, committedCharacters } from '#lib/core/testing/committed-data.ts';
import { abilityState } from '#lib/core/rules/ability.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { nightStepAlerts } from '#lib/core/rules/night-alerts.ts';
import { scenario, type Scenario } from '#lib/core/testing/scenario.ts';
import { allEvilBecomeTests, scriptOf } from './legion.test-support.ts';

describe('Engineer + Legion jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'engineer', 'legion');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('engineer')?.name).toBe('Engineer');
		expect(data.byId.get('legion')?.name).toBe('Legion');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['engineer', 'legion'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['engineer'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['legion'])).not.toContain(jinx);
	});

	it('is data in both rules', () => {
		expect(jinxRulesBetween('engineer', 'legion', committedCharacters())).toEqual({
			impairs: { kind: 'no-ability', when: ['partner-in-play'] },
			learns: { what: 'no-ability', when: [{ night: 1 }] },
			allEvilBecome: {}
		});
	});

	allEvilBecomeTests('engineer');

	// The Engineer's Related Jinxes: with Legion in play the Engineer has no ability, and learns
	// this on the first night.
	describe('with Legion in play the Engineer starts knowing they have no ability', () => {
		const script = scriptOf(['engineer', 'legion', 'imp', 'chef', 'empath', 'monk']);
		const base = scenario(['legion', 'legion', 'legion', 'engineer', 'chef', 'empath'], {
			script
		});
		const learns = (s: Scenario) =>
			nightStepAlerts(s.game, 'engineer', s.characters).filter(
				(a) => a.kind === 'learns-no-ability'
			);

		it('takes the Engineer ability while Legion is in play', () => {
			// Wiki: "If Legion is in play, the Engineer starts knowing this but has no ability."
			const state = abilityState(base.game, base.seat('engineer'), base.characters);
			expect(state.works).toBe(false);
			expect(state.impairments.map((i) => [i.reason, i.source.characterId])).toEqual([
				['no-ability', 'legion']
			]);
			const none = scenario(['imp', 'engineer', 'chef', 'empath', 'monk'], { script });
			expect(abilityState(none.game, none.seat('engineer'), none.characters).works).toBe(true);
		});

		it("learns this at the Engineer's step on the first night only", () => {
			// Wiki: "If Legion is in play, the Engineer starts knowing this but has no ability."
			expect(learns(base)).toMatchObject([
				{
					seatId: base.seat('engineer'),
					source: { characterId: 'engineer' },
					partner: 'legion',
					works: true
				}
			]);
			expect(learns(base.newDay().dusk())).toEqual([]);
			const none = scenario(['imp', 'engineer', 'chef', 'empath', 'monk'], { script });
			expect(learns(none)).toEqual([]);
		});
	});
});
